window.ox.install(({action})=>{
const clean=s=>(s||'').replace(/\s+/g,' ').trim();
function check(){if(/just a moment|verify you are human|access denied|security verification/i.test(document.title)||document.querySelector('#challenge-running,#awswaf-captcha-container'))throw new Error('Human verification required. Show this action page and wait for the user.');}
async function wait(fn){const end=Date.now()+12000;while(Date.now()<end){check();const v=fn();if(v)return v;await new Promise(r=>setTimeout(r,120));}throw new Error('DeepSeek page not ready: expected content did not appear; inspect the live action page.');}
async function index(){if(location.pathname!=='/en/news/'&&location.pathname!=='/en/news'){check();const back=Array.from(document.querySelectorAll('a[href]')).find(a=>a.getAttribute('href')==='/en/news/');if(!back)throw new Error('News index navigation link missing on current page.');back.click();}await wait(()=>(location.pathname==='/en/news/'||location.pathname==='/en/news')&&document.querySelector('main .ds-news-hero-card h2'));}
action('listPosts',{async invoke(args){await index();const b=Array.from(document.querySelectorAll('main button')).find(e=>clean(e.textContent)==='View All');if(b){const n=document.querySelectorAll('main a[href]').length;b.click();await wait(()=>document.querySelectorAll('main a[href]').length>n&&!Array.from(document.querySelectorAll('main button')).some(e=>clean(e.textContent)==='View All'));}const all=Array.from(document.querySelectorAll('main a.ds-news-hero-card,main a.ds-news-list-item')).map(a=>{const date=a.querySelector('p span.text-ds-description');const paragraphs=a.querySelectorAll('p');return {title:clean(a.querySelector('h2,h3')?.textContent),url:new URL(a.getAttribute('href'),location.origin).href,date:clean(date?.textContent)||null,excerpt:clean(paragraphs[paragraphs.length-1]?.textContent)||null};});if(!all.length||all.some(p=>!p.title))throw new Error('Incomplete news listing structure.');const limit=args.limit??100;return {items:all.slice(0,limit),nextCursor:null,coverage:all.length<=limit?'complete':'partial'};}});
action('listResearch',{async invoke(args){await index();const all=Array.from(document.querySelectorAll('a.ds-research-item')).map(a=>({title:clean(a.querySelector('.ds-research-title')?.textContent),url:a.href,date:clean(a.querySelector('.ds-research-date')?.textContent)||null,excerpt:null}));if(!all.length||all.some(p=>!p.title))throw new Error('Research index not loaded or changed.');return {items:all.slice(0,args.limit??100),nextCursor:null,coverage:'partial'};}});
action('getPost',{async invoke(args){const u=new URL(args.url);if(u.protocol!=='https:'||u.hostname!=='www.deepseek.com'||!/^\/en\/news\/[^/]+\/?$/.test(u.pathname)||u.search||u.hash)throw new Error('Expected a public DeepSeek English news article URL.');await index();const b=Array.from(document.querySelectorAll('main button')).find(e=>clean(e.textContent)==='View All');if(b){const n=document.querySelectorAll('main a[href]').length;b.click();await wait(()=>document.querySelectorAll('main a[href]').length>n);}const link=Array.from(document.querySelectorAll('main a[href]')).find(e=>e.href===u.href);if(!link)throw new Error('Article not found in the source news listing.');const expected=clean(link.querySelector('h2,h3')?.textContent);const sourceDate=clean(link.querySelector('p span.text-ds-description')?.textContent)||null;link.click();const main=await wait(()=>{const m=document.querySelector('main article.ds-blog-article');return location.pathname===u.pathname&&m&&clean(document.querySelector('h1')?.textContent)===expected&&clean(m.textContent).length>300?m:null;});const clone=main.cloneNode(true);for(const img of clone.querySelectorAll('img')){img.replaceWith(document.createTextNode('[Image: '+(img.alt||'chart or illustration')+']'));}for(const e of clone.querySelectorAll('script,style,nav,button,aside,[aria-hidden="true"]'))e.remove();const links=Array.from(clone.querySelectorAll('a[href]')).map(a=>({title:clean(a.textContent),url:new URL(a.getAttribute('href'),location.href).href})).filter(a=>a.title&&/^https?:/.test(a.url)).slice(0,200);for(const e of clone.querySelectorAll('p,h1,h2,h3,h4,li,pre,blockquote,figcaption,div,section,tr'))e.appendChild(document.createTextNode('\n\n'));const text=clone.textContent.replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim();if(text.length<300||text.length>200000)throw new Error('Article text missing or outside safe bounds.');return {title:clean(document.querySelector('h1')?.textContent||document.title),url:location.href,date:main.querySelector('time')?.getAttribute('datetime')||sourceDate,text,links};}});
});